using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Audit;[Authorize(Policy="PlatformAuditRead")]public sealed class IndexModel(OrcaFacilDbContext db):PageModel{public IReadOnlyList<Row>Items{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct)=>Items=await db.AccountModuleAuditLogs.AsNoTracking().Where(x=>!x.IsDeleted).OrderByDescending(x=>x.CreatedAt).Take(200).Select(x=>new Row(x.CreatedAt,x.Action,x.AccountId.HasValue?x.AccountId.Value.ToString():"Global",x.ModuleCode??"—",x.Summary,x.CorrelationId)).ToListAsync(ct);public sealed record Row(DateTime At,string Action,string Account,string Module,string Summary,string Correlation);}
